from pathlib import Path
import json,base64
p=Path(__file__).resolve().parents[1]
m=json.loads((p/'map-ain-v15.tmj').read_text());image=base64.b64encode((p/'ain_conference_v15.png').read_bytes()).decode()
html='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AIN — перевірка маршрутів</title><style>body{margin:0;background:#111528;color:white;font:15px system-ui}header{padding:16px 24px;display:flex;align-items:center;gap:20px;flex-wrap:wrap}button{padding:8px 14px;cursor:pointer}canvas{display:block;width:100%;height:auto}small{color:#b7bfdc}</style><header><strong>AIN · Кібербезпека</strong><span>Рух: WASD / стрілки. Клік — перейти до точки доступним маршрутом.</span><button id="walls">Межі руху</button><small>Локальний тест геометрії. Відеозв’язок і навантаження WorkAdventure тут не перевіряються.</small></header><canvas id="map" width="1280" height="768"></canvas><script>
const M=__MAP__,C=document.querySelector('canvas'),ctx=C.getContext('2d'),W=M.width,H=M.height,cell=8;
const blocks=M.layers[1].data,start=M.layers[3].data.findIndex(Boolean);let pos={x:start%W+.5,y:Math.floor(start/W)+.5},show=false,path=[],keys={};
const img=new Image();img.src='data:image/png;base64,__IMAGE__';
const free=(x,y)=>x>=0&&y>=0&&x<W&&y<H&&!blocks[Math.floor(y)*W+Math.floor(x)];
function move(dx,dy){const r=.22;let x=pos.x+dx,y=pos.y+dy;if([[x-r,y-r],[x+r,y-r],[x-r,y+r],[x+r,y+r]].every(p=>free(...p)))pos={x,y};}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys[e.key]=true;path=[];}});addEventListener('keyup',e=>keys[e.key]=false);addEventListener('blur',()=>keys={});
document.querySelector('button').onclick=()=>show=!show;
C.onclick=e=>{const r=C.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*W),y=Math.floor((e.clientY-r.top)/r.height*H),dest=y*W+x,src=Math.floor(pos.y)*W+Math.floor(pos.x);if(!free(x,y))return;const queue=[src],prev=new Map([[src,null]]);for(let j=0;j<queue.length;j++){let i=queue[j];if(i===dest)break;for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let xx=i%W+dx,yy=Math.floor(i/W)+dy,n=yy*W+xx;if(free(xx,yy)&&!prev.has(n)){prev.set(n,i);queue.push(n);}}}if(!prev.has(dest))return;path=[];for(let n=dest;n!==src;n=prev.get(n))path.unshift({x:n%W+.5,y:Math.floor(n/W)+.5});};
let last=0;function frame(t){let dt=Math.min((t-last)/1000,.04);last=t;let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(dx||dy){let l=Math.hypot(dx,dy);move(dx/l*dt*10,0);move(0,dy/l*dt*10);}else if(path.length){let n=path[0],dx=n.x-pos.x,dy=n.y-pos.y,l=Math.hypot(dx,dy),step=dt*10;if(l<=step){pos=n;path.shift();}else move(dx/l*step,dy/l*step);}ctx.clearRect(0,0,1280,768);if(img.complete)ctx.drawImage(img,0,0,1280,768);if(show){ctx.fillStyle='#ff335577';blocks.forEach((b,i)=>{if(b)ctx.fillRect(i%W*cell,Math.floor(i/W)*cell,cell,cell);});}ctx.fillStyle='#00edcd88';path.forEach(n=>ctx.fillRect(n.x*cell-1,n.y*cell-1,2,2));ctx.fillStyle='#fff';ctx.strokeStyle='#121827';ctx.lineWidth=2;ctx.beginPath();ctx.arc(pos.x*cell,pos.y*cell,4,0,Math.PI*2);ctx.fill();ctx.stroke();requestAnimationFrame(frame);}requestAnimationFrame(frame);
</script></html>'''
(p/'walk-test-v15.html').write_text(html.replace('__MAP__',json.dumps(m,separators=(',',':'))).replace('__IMAGE__',image))
